Example to deploy a contract that will allow deposits between 100gwei min and 3200gwei max and the chain starts at 8 validators:

```
bazel run //contracts/deposit-contract/deployContract -- \
  --httpPath=http://goerli.prylabs.net \
   --privKey=$(cat /path/to/raw-private-key) \
   --chain-start=8 --min-deposit=100 --max-deposit=3200
```

The example config above was deployed to Goerli at [0xaeB64d81C0d0E71db596F97e08D40b1dbD880389](http://lite.goerli.ethstats.surge.sh/#/account/0xaeb64d81c0d0e71db596f97e08d40b1dbd880389)

Note: I was able to start the chain at the above contract! Here are the steps I took to see a chain start.

Step 0: Deploy the contract somewhere

Step 1: Configure your metamask to use the prylabs node (http://goerli.prylabs.net).

Step 2: Launch your beacon-chain node with  `--web3provider=ws://goerli.prylabs.net/websocket` (and other necessary flags).

Step 3: Create some account via `bazel //validator -- accounts create --keystore=/tmp/keystore --password=/dev/null`

Step 4: Use the output of that as the input in the data in the code below. Run this in your chrome console with a metamask account selected with some funds. This will use a very small amount.

```javascript
var address = "0xaeB64d81C0d0E71db596F97e08D40b1dbD880389"; // change me!
var d = web3.eth.contract([{"name": "Deposit", "inputs": [{"type": "bytes32", "name": "previous_deposit_root", "indexed": false}, {"type": "bytes", "name": "data", "indexed": false}, {"type": "bytes", "name": "merkle_tree_index", "indexed": false}], "anonymous": false, "type": "event"}, {"name": "ChainStart", "inputs": [{"type": "bytes32", "name": "deposit_root", "indexed": false}, {"type": "bytes", "name": "time", "indexed": false}], "anonymous": false, "type": "event"}, {"name": "__init__", "outputs": [], "inputs": [{"type": "uint256", "name": "depositThreshold"}, {"type": "uint256", "name": "minDeposit"}, {"type": "uint256", "name": "maxDeposit"}], "constant": false, "payable": false, "type": "constructor"}, {"name": "get_deposit_root", "outputs": [{"type": "bytes32", "name": "out"}], "inputs": [], "constant": true, "payable": false, "type": "function", "gas": 625}, {"name": "deposit", "outputs": [], "inputs": [{"type": "bytes", "name": "deposit_input"}], "constant": false, "payable": true, "type": "function", "gas": 1711311}, {"name": "get_branch", "outputs": [{"type": "bytes32[32]", "name": "out"}], "inputs": [{"type": "uint256", "name": "leaf"}], "constant": true, "payable": false, "type": "function", "gas": 20138}]).at(address);

var cb = function(idk, receipt) {
  console.log("TX = " + receipt);
};

// The parameter here is the output from validator accounts create
var data = d.deposit.getData("");

for (var i = 0; i < 8; i++) {
  web3.eth.sendTransaction({to: d.address, value: web3.toWei(3200, 'gwei'), data: data}, cb);
}
```

Step 5: Beacon chain starts

